suspend fun saveVideoToGallery(context: Context, clip: Clip): String {    if (clip.type != Clip.CLIP_TYPE_ORIGINAL_DATA) {        /**         * FIXME: 目前不支持编辑已经是MP4的文件, 暂时全部返回原视频         *  收藏页 -&gt; 添加拍摄者水印         *  非本人拍摄(app内分享) -&gt; 添加拍摄者水印         *  已经有水印(识别视频) -&gt; 直接保存原视频         * */        logger.w(TAG, "clip type is not original data")        val nonOriMP4Path = clip.nonOriginalData?.get(Clip.NonOriginalData.KEY_MP4_PATH)        return if (nonOriMP4Path != null &amp;&amp; File(nonOriMP4Path).exists()) {            copyToMediaStore(context, File(nonOriMP4Path))        } else {            ""        }    }    return if (Build.VERSION.SDK_INT &lt; Build.VERSION_CODES.Q) {        saveVideoBeforeQ(context, clip)    } else {        saveVideo(context, clip)    }}

其中copyToMediaStore(context, File(nonOriMP4Path))是用于将视频拷贝到相册
