具体的扫描过程是使用ScanUtil类，插入代码是RegisterCodeGenerator类。
class ScanUtil {    //扫描jar    static void scanJar(File jarFile, File destFile) {        if (jarFile) {            def file = new JarFile(jarFile)            Enumeration enumeration = file.entries()            while (enumeration.hasMoreElements()) { //遍历jar里面的所有class文件                JarEntry jarEntry = (JarEntry) enumeration.nextElement()                String entryName = jarEntry.getName()                if (entryName.startsWith(ScanSetting.ROUTER_CLASS_PACKAGE_NAME)) {//找到包名是'com/alibaba/android/arouter/routes/'的class                    InputStream inputStream = file.getInputStream(jarEntry)                    scanClass(inputStream) //也是走scanClass方法                    inputStream.close()                } else if (ScanSetting.GENERATE_TO_CLASS_FILE_NAME == entryName) {//LogisticsCenter，物流中心，是在jar中                    // 记录包含 LogisticsCenter.class 的jar文件，扫描完成后会向其中插入代码                    RegisterTransform.fileContainsInitClass = destFile                }            }            file.close()        }    }...    //扫描class文件    static void scanClass(File file) {        scanClass(new FileInputStream(file))    }    //扫描class，inputStream class文件的输入流（从transform中获取的）    static void scanClass(InputStream inputStream) {        ClassReader cr = new ClassReader(inputStream)        ClassWriter cw = new ClassWriter(cr, 0)        ScanClassVisitor cv = new ScanClassVisitor(Opcodes.ASM5, cw)        cr.accept(cv, ClassReader.EXPAND_FRAMES)        inputStream.close()    }    static class ScanClassVisitor extends ClassVisitor {        ...        //该方法主要提供对java版本，类权限访问符、全限定名、泛型、父类、接口相关信息        void visit(int version, int access, String name, String signature,String superName, String[] interfaces) {            super.visit(version, access, name, signature, superName, interfaces)            //按类实现的接口，分别存到 RegisterTransform.registerList对应ScanSetting#classList中            RegisterTransform.registerList.each { ext -&gt;                if (ext.interfaceName &amp;&amp; interfaces != null) {                    interfaces.each { itName -&gt;                        if (itName == ext.interfaceName) {                            if (!ext.classList.contains(name)) {                                ext.classList.add(name)                            }                        }                    }                }            }        }    }}

无论是jar还是目录，都是找到包名是 com/alibaba/android/arouter/routes/的class文件，然后通过class文件的输入流，使用ASM读取class文件内容，再自定义ScanClassVisitor在visit()方法，按类实现的接口找到所有的帮助类，存到 RegisterTransform.registerList对应的ScanSetting.classList中。
动态代码注入代码插入的过程：
class RegisterCodeGenerator {    ...    static void insertInitCodeTo(ScanSetting registerSetting) {        if (registerSetting != null &amp;&amp; !registerSetting.classList.isEmpty()) {            RegisterCodeGenerator processor = new RegisterCodeGenerator(registerSetting)            //包含LogisticsCenter.class的jar文件            File file = RegisterTransform.fileContainsInitClass            if (file.getName().endsWith('.jar'))                processor.insertInitCodeIntoJarFile(file)        }    }    //插入代码到jar    private File insertInitCodeIntoJarFile(File jarFile) {        if (jarFile) {            ...            def file = new JarFile(jarFile)            Enumeration enumeration = file.entries()            JarOutputStream jarOutputStream = new JarOutputStream(new FileOutputStream(optJar))            while (enumeration.hasMoreElements()) {                JarEntry jarEntry = (JarEntry) enumeration.nextElement()                String entryName = jarEntry.getName()                ZipEntry zipEntry = new ZipEntry(entryName)                InputStream inputStream = file.getInputStream(jarEntry)                jarOutputStream.putNextEntry(zipEntry)                //找到类 LogisticsCenter                if (ScanSetting.GENERATE_TO_CLASS_FILE_NAME == entryName) {                    //拿到LogisticsCenter.class文件的输入流，开始插代码!!!                    def bytes = referHackWhenInit(inputStream)                                        jarOutputStream.write(bytes)                } else {                    jarOutputStream.write(IOUtils.toByteArray(inputStream))                }                ...            }            ...            optJar.renameTo(jarFile)        }        return jarFile    }    //使用ASM插入代码    private byte[] referHackWhenInit(InputStream inputStream) {        ClassReader cr = new ClassReader(inputStream)        ClassWriter cw = new ClassWriter(cr, 0)        ClassVisitor cv = new MyClassVisitor(Opcodes.ASM5, cw)        cr.accept(cv, ClassReader.EXPAND_FRAMES)        return cw.toByteArray()    }    class MyClassVisitor extends ClassVisitor {        ...        @Override        MethodVisitor visitMethod(int access, String name, String desc, String signature, String[] exceptions) {            MethodVisitor mv = super.visitMethod(access, name, desc, signature, exceptions)            //找到要插入代码的方法-loadRouterMap            if (name == ScanSetting.GENERATE_TO_METHOD_NAME) {                mv = new RouteMethodVisitor(Opcodes.ASM5, mv)            }            return mv        }    }    class RouteMethodVisitor extends MethodVisitor {    ..        @Override        void visitInsn(int opcode) {            //在return之前插入代码            if ((opcode &gt;= Opcodes.IRETURN &amp;&amp; opcode &lt;= Opcodes.RETURN)) {                extension.classList.each { name -&gt;                    name = name.replaceAll("/", ".")//把帮助类路径中的"/"换成"."                    mv.visitLdcInsn(name)//帮助类类名                    //在LogisticsCenter.loadRouterMap()中添加代码：register(name)，name就是 根帮助类/拦截器帮助类/服务帮助类 类名                    mv.visitMethodInsn(Opcodes.INVOKESTATIC                            , ScanSetting.GENERATE_TO_CLASS_NAME                            , ScanSetting.REGISTER_METHOD_NAME                            , "(Ljava/lang/String;)V"                            , false)                }            }            super.visitInsn(opcode)        }        ...    }}


首先是拿到jar中LogisticsCenter.class文件的输入流
接着使用ASM自定义MyClassVisitor在visitMethod()方法中找到要插入代码的方法-loadRouterMap()
然后在自定义RouteMethodVisitor的visitInsn()方法中，确保在return之前插入代码
