void startSpecificActivityLocked(  ActivityRecord r,  boolean andResume,   boolean checkConfig) {  //获取即将要启动的Activity的所在的应用程序进程  ProcessRecord app = mService.getProcessRecordLocked(r.processName,          r.info.applicationInfo.uid, true);  //如果应用进程已经存在  if (app != null &amp;&amp; app.thread != null) {    try {      if ((r.info.flags&amp;ActivityInfo.FLAG_MULTIPROCESS) == 0              || !"android".equals(r.info.packageName)) {        // Don't add this if it is a platform component that is marked        // to run in multiple processes, because this is actually        // part of the framework so doesn't make sense to track as a        // separate apk in the process.        app.addPackage(r.info.packageName, r.info.applicationInfo.longVersionCode, mService.mProcessStats);      }      realStartActivityLocked(r, app, andResume, checkConfig);      return;    } catch (RemoteException e) {        Slog.w(TAG, "Exception when starting activity "                + r.intent.getComponent().flattenToShortString(), e);    }    // If a dead object exception was thrown -- fall through to    // restart the application.  }  //应用进程还未创建，则通过AMS调用startProcessLocked向Zygote进程发送请求  mService.startProcessLocked(r.processName, r.info.applicationInfo, true, 0,"activity", r.intent.getComponent(), false, false, true);}

在方法中首先获取到了即将要启动的Activity所在的应用进程，假如是普通的Activity的启动流程的活，这个进程肯定是存在的，所以将执行realStartActivityLocked的方法。但是我们现在讨论的是根Activity的启动流程，由于应用都还未启动，意味着根Activity所在的应用进程还未创建，而mService其实就是AMS，所以这里将调用AMS的startProcessLocked。
    private final boolean startProcessLocked(ProcessRecord app, String hostingType,            String hostingNameStr, boolean disableHiddenApiChecks, String abiOverride) {       ...            int uid = app.uid; //创建应用进程的用户ID            int[] gids = null;            int mountExternal = Zygote.MOUNT_EXTERNAL_NONE;            if (!app.isolated) {                ...                /*                 * 对用户组进行创建和赋值                 */                if (ArrayUtils.isEmpty(permGids)) {                    gids = new int[3];                } else {                    gids = new int[permGids.length + 3];                    System.arraycopy(permGids, 0, gids, 3, permGids.length);                }                gids[0] = UserHandle.getSharedAppGid(UserHandle.getAppId(uid));                gids[1] = UserHandle.getCacheAppGid(UserHandle.getAppId(uid));                gids[2] = UserHandle.getUserGid(UserHandle.getUserId(uid));                // Replace any invalid GIDs                if (gids[0] == UserHandle.ERR_GID) gids[0] = gids[2];                if (gids[1] == UserHandle.ERR_GID) gids[1] = gids[2];            }            ...            //这个参数后文会提到            final String entryPoint = "android.app.ActivityThread";                return startProcessLocked(...);            }    private boolean startProcessLocked(...) {      ....        //重点关注        final ProcessStartResult startResult = startProcess(...);        ...    }private ProcessStartResult startProcess(...) {        ....  if (hostingType.equals("webview_service")) {      startResult = startWebView(entryPoint,              app.processName, uid, uid, gids, runtimeFlags, mountExternal,              app.info.targetSdkVersion, seInfo, requiredAbi, instructionSet,              app.info.dataDir, null,              new String[] {PROC_START_SEQ_IDENT + app.startSeq});  } else {  //通过Process.start方法来为应用创建进程      startResult = Process.start(entryPoint,              app.processName, uid, uid, gids, runtimeFlags, mountExternal,   