在startProcess方法里将调用Process.start来发送应用创建进程的请求。这样AMS就将发送请求的事交给了Process
Process向Zygote进程发送创建应用进程请求public static final ProcessStartResult start(...) {    return ZYGOTE_PROCESS.start(...);}public final Process.ProcessStartResult start(...) {    try {      //重点关注      return startViaZygote(...);    } catch (ZygoteStartFailedEx ex) {    }}private Process.ProcessStartResult startViaZygote(...) throws ZygoteStartFailedEx {        ArrayList&lt;String&gt; argsForZygote = new ArrayList&lt;String&gt;();        // --runtime-args, --setuid=, --setgid=,        //创建字符串列表argsForZygote，并将启动应用进程的启动参数保存在这个列表中        argsForZygote.add("--runtime-args");        argsForZygote.add("--setuid=" + uid);        argsForZygote.add("--setgid=" + gid);        argsForZygote.add("--runtime-flags=" + runtimeFlags);        if (mountExternal == Zygote.MOUNT_EXTERNAL_DEFAULT) {            argsForZygote.add("--mount-external-default");        } else if (mountExternal == Zygote.MOUNT_EXTERNAL_READ) {            argsForZygote.add("--mount-external-read");        } else if (mountExternal == Zygote.MOUNT_EXTERNAL_WRITE) {            argsForZygote.add("--mount-external-write");        }        argsForZygote.add("--target-sdk-version=" + targetSdkVersion);        ...        synchronized(mLock) {		      //重点关注          return zygoteSendArgsAndGetResult(openZygoteSocketIfNeeded(abi),                                              useBlastulaPool,                                              argsForZygote);        }    }
在startViaZygote中会创建字符串列表argsForZygote来保存将要创建的应用进程的启动参数，然后最后会调用zygoteSendArgsAndGetResult方法，而在这个方法中第一个参数会调用openZygoteSocketIfNeeded方法，第三个参数就是启动参数列表。
拓扑排序视频讲解
public static startupSortStore sort(List&lt;? extends startup&lt;?&gt;&gt;startupList){  //入度表  Map&lt;Class&lt;? extends startup&gt;, Integer&gt;inDegreeMap= new HashMap&lt;&gt;();  //0度表  Deque&lt;Class&lt;? extends Startup&gt;&gt;zeroDeque = new ArrayDeque&lt;&gt;();  //任务表 用于保存原图  Map&lt;Class&lt;? extends Startup&gt;,Startup&lt;?&gt;&gt; startupMap = new HashMap&lt;&gt;();  //任务依赖表  Map&lt;Class&lt;? extends startup&gt;, List&lt;Class&lt;? extends Startup&gt;&gt;&gt; startupchildrenMap = new HashMap&lt;&gt;();    // 1.找出图中入度数为0的节点填表的过程  for(startup&lt;?&gt;startup :startupList){    startupMap.put(startup.getClass()，startup);    //记录每个任务的入度数(依赖的任务数)    int dependenciesCount=startup.getDependenciesCount();    inDegreeMap.put(startup.getclass(),dependenciescount);    //记录入度数(依赖的任务数)为0的任务    if(dependenciesCount==0) {      zeroDeque.offer(startup.getclass());    } else {      //遍历本任务的依赖任务，生成任务依赖表      for(Class&lt;? extends startup&lt;?&gt;&gt;parent : startup.dependencies()){        List&lt;Class&lt;? extends startup&gt;&gt;children = startupchildrenMap.get(parent);        if(children == null){          children = new ArrayList&lt;&gt;();          //记录这个父任务的所有子任务          startupchildrenMap.put(parent,children);        }        children.add(startup.getclass());      }    }  }  // 2.删除图中入度为0的这些顶点，并更新全图，，最后完成排序  List&lt;Startup&lt;?&gt;&gt;result = new ArrayList&lt;&gt;();  //处理入度为0的任务  while(!zeroDeque.isEmpty()) {    Class&lt;?extends startup&gt;cls =zeroDeque.poll();    Startup&lt;?&gt;startup =startupMap.get(cls);result.add(startup);    //删除此入度为0的任务    if(startupChildrenMap.containsKey(cls)){      List&lt;Class&lt;? extends startup&gt;&gt;childstartup = startupchildrenMap.get(cls);      for(Class&lt;?extends startup&gt;childcls :childstartup){        Integer num=inDegreeMap.get(childcls);        inDegreeMap.put(childcls，num-1);        if(num-1==0){          zeroDeque.offer(childcls);        }      }    }  }    return new StartupSortStore(result, startupMap, startupchildrenMap);}

