     }, onError = {                logger.w(TAG, "load assist, buffer, error", it)            })    }  	/**  	* 这里用到了startActivityForResult，用于页面带参数返回，参考  	* https://blog.csdn.net/weixin_41008021/article/details/90346700  	*/    @Deprecated("Deprecated in Java")    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {        super.onActivityResult(requestCode, resultCode, data)        when (requestCode) {            REQUEST_CODE -&gt; {                if (resultCode == Activity.RESULT_OK) {                    if (data != null) {                        viewModel.setName(data.getStringExtra(Constants.EXTRA_SEARCH_MAIN_POSITION))                    }                }            }        }    }}



