.notifyDataSetChanged()        }    }    /**     * 设置名称     * */    @SuppressLint("NotifyDataSetChanged")    fun setName(name: String?) {        logger.d(TAG, "setName, name = $name")        currentUserName.set(name)    }    /**     * 点击设置名称     * */    @Suppress("UNUSED_PARAMETER") // View.OnClickListener    fun onClickSetFriend(view: View) {        val intent = Intent().apply {            putExtra(                BaseNavigation.Constants.EXTRA_SEARCH_MAIN_POSITION,                mainPosition,            )        }      	// BaseNavigation封装的方法        navigationRequiredEvent.postValue(            BaseNavigation(                BaseNavigation.Route.USER_FACE_FRIEND_LIST,                intent,                true,                REQUEST_CODE            )        )    }    override fun onClickItem(viewHolder: ThumbnailAdapter.ThumbnailViewHolder) {        logger.d(TAG, "viewHolder=$viewHolder")    }}

这里的跳转用到了onActivityResult， 使用的是BaseNavigation封装后的方法，第三个参数为是否开启startForResult，第四个参数是标志
封装的方法如下：
fun launch(fromActivity: Activity, intent: Intent? = null) {  val finalIntent = Intent(fromActivity, route.activityClass)  paramIntent?.let { finalIntent.putExtras(it) }  intent?.let { finalIntent.putExtras(it) }  if (startForResult) {      fromActivity.startActivityForResult(finalIntent, requestCode, requestBundle)  } else {      fromActivity.startActivity(finalIntent)  }}

