package com.danale.edge.ui.userfaceimport android.annotation.SuppressLintimport android.app.Activityimport android.content.Intentimport android.os.Bundleimport androidx.activity.viewModelsimport com.danale.edge.Rimport com.danale.edge.base.BaseActivityimport com.danale.edge.base.BaseNavigationimport dagger.hilt.android.AndroidEntryPointimport kotlinx.coroutines.*@AndroidEntryPointclass UserFaceFriendListActivity : BaseActivity() {    private val viewModel: UserFaceFriendListViewModel by viewModels()    @SuppressLint("SuspiciousIndentation")    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        setContentView(R.layout.activity_user_face_friend_list)        // 第一次跳转过来的时候拿到点击的下标        val mainPosition =            intent?.getIntExtra(BaseNavigation.Constants.EXTRA_SEARCH_MAIN_POSITION, 0)        if (mainPosition != null) {            viewModel.setPosition(mainPosition)        }        MainScope().launch {            viewModel.loadPlatformContactList()        }    }    override fun onResume() {        super.onResume()        viewModel.navigationRequiredEvent.observe(this) {            it?.launch(this)        }        observeNavigation(viewModel)        // 非首次跳转        // 监听viewModel的liveData        viewModel.liveData.observe(this) {            val intent = Intent().apply {                putExtra(                    BaseNavigation.Constants.EXTRA_SEARCH_MAIN_POSITION,                    it,                )            }            // 返回上一页面            setResult(Activity.RESULT_OK, intent)            finish()        }    }}

