   } catch (e: Exception) {                toastError(e)                null            }        }        logger.d(TAG, "loadStarFriendList, starUserList=$starUserList")    }    /**     * 加载好友列表     */    private suspend fun loadPlatformContactList(refresh: Boolean = false) {        try {            // 获取的星标列表            loadStarFriendList()            val nonNullList = starUserList?.deviceIdList ?: emptyList()            if (nonNullList.isNotEmpty()) nonNullList.forEach {                starUserMap[it.userName] = true            }            // 获取的好友列表            withContext(Dispatchers.IO) {                sdk.getFriendsList(forceReFetch = refresh).awaitLast()?.map { it -&gt;                    // 用户名                    val displayName = if (it.remarkName?.isNotEmpty() == true) {                        it.remarkName                    } else {                        it.likeName                    }                    // 用户头像                    val url = withContext(Dispatchers.IO) {                        it.userName?.let { it1 -&gt;                            sdk.getPhotoUrlByPlatformUserName(it1).awaitSingleOrNull()                        }                    }                    // 添加数据                    starFriendList.add(                        StarFriend(                            displayName,                            url,                            starUserMap[it.userName] !== null,                            it.userName                        )                    )                }            }            logger.i(TAG, "loadPlatformContactList, starFriendList= $starFriendList")            // 构建列表            buildSettingItems()        } catch (e: Exception) {            toastError(e)        }    }    // 构建列表    private fun buildSettingItems() {        starUserAdapter.apply {            add(Section().apply {                for ((i, item) in starFriendList.withIndex()) {                    item.url?.let { url -&gt;                        item.name?.let { name -&gt;                            StarUserItem(                                list = starFriendList,  // 传入最新的列表获得isStar属性                                avatar = url,  // 头像链接                                name = name,  // 用户名                                clickListener = { _ -&gt;                                    if (!item.isStar) {                                        // 存                                        viewModelScope.launch {                                            withContext(Dispatchers.IO) {                                                try {                                                    deviceId32?.let { did -&gt;                                                        item.nameId?.let { nameId -&gt;                                                            sdk.storeStarUser(                                                                did,                                                                nameId                                                            ).await()                                                        }                                                    }                                                    // 更新列表                                                    starFriendList[i] =                                                        StarFriend(name, url, true, item.nameId)                                                } catch (e: Exception) {                                                    logger.d(TAG, "error, $e")                                                }                                            }                                          	// 通知Adapter刷新数据                                            starUserAdapter.notifyItemChanged(i, 0)                                        }                                     } else {                                        // 删                                        viewModelScope.launch {                                            withContext(Dispatchers.IO) {                                                try {                                                    deviceId32?.let { did -&gt;                                                        item.nameId?.let { nameId -&gt;                                                            sdk.deleteStarUser(                                                                did,                                                                nameId                                                            ).await()                                                        }                                                    }                                                    starFriendList[i] =                                                        StarFriend(name, url, false, item.nameId)                                                } catch (e: Exception) {                                                    logger.d(TAG, "error, $e")                                                }                                            }                                            starUserAdapter.notifyItemChanged(i, 0)                                        }                                    }                                }                            )                        }                    }?.let { StarUserItem -&gt;                        add(                            StarUserItem                        )                    }                }            })        }    }    override fun onClickItem(viewHolder: RecyclerListViewHolder) {        logger.d(TAG, "onClickItem, viewHolder=$viewHolder")    }}



