package com.danale.edge.ui.common.groupieimport android.annotation.SuppressLintimport android.view.Viewimport androidx.databinding.DataBindingUtilimport coil.loadimport coil.transform.RoundedCornersTransformationimport com.danale.edge.Rimport com.danale.edge.databinding.RecyclerGroupieItemStarUserBindingimport com.danale.edge.ui.devicecontrol.common.StarUserViewModelimport com.xwray.groupie.viewbinding.BindableItemclass StarUserItem(    var list: ArrayList&lt;StarUserViewModel.StarFriend&gt; = ArrayList(),    var avatar: String,    var name: String = "",    val clickListener: ((View) -&gt; Unit)? = null) : BindableItem&lt;RecyclerGroupieItemStarUserBinding&gt;() {    @SuppressLint("ClickableViewAccessibility")    override fun bind(viewBinding: RecyclerGroupieItemStarUserBinding, position: Int) {        viewBinding.let {            it.ivUserAvatar.load(this.avatar) {                placeholder(R.mipmap.clipart_default_avatar_round)                error(R.mipmap.clipart_default_avatar_round)                transformations(RoundedCornersTransformation(36f))            }            it.name = this.name            it.switchAccessory.isSelected = this.list[position].isStar            it.switchAccessory.setOnClickListener(clickListener)        }    }    override fun getLayout(): Int {        return R.layout.recycler_groupie_item_star_user    }    override fun initializeViewBinding(view: View): RecyclerGroupieItemStarUserBinding {        return DataBindingUtil.bind(view) ?: throw IllegalStateException("unable to bind view")    }}


