ExchangeFinder.kt
fun find(    client: OkHttpClient,    chain: RealInterceptorChain): ExchangeCodec {    try {        //查找合格可用的连接，返回一个 RealConnection 对象        val resultConnection = findHealthyConnection(            connectTimeout = chain.connectTimeoutMillis,            readTimeout = chain.readTimeoutMillis,            writeTimeout = chain.writeTimeoutMillis,            pingIntervalMillis = client.pingIntervalMillis,            connectionRetryEnabled = client.retryOnConnectionFailure,            doExtensiveHealthChecks = chain.request.method != "GET"        )        //根据连接，创建并返回一个请求响应编码器：Http1ExchangeCodec 或者 Http2ExchangeCodec，分别对应Http1协议与Http2协议        return resultConnection.newCodec(client, chain)    } catch (e: RouteException) {        trackFailure(e.lastConnectException)        throw e    } catch (e: IOException) {        trackFailure(e)        throw RouteException(e)    }}

