private fun findHealthyConnection(    connectTimeout: Int,    readTimeout: Int,    writeTimeout: Int,    pingIntervalMillis: Int,    connectionRetryEnabled: Boolean,    doExtensiveHealthChecks: Boolean): RealConnection {    while (true) {        //重点：查找连接        val candidate = findConnection(            connectTimeout = connectTimeout,            readTimeout = readTimeout,            writeTimeout = writeTimeout,            pingIntervalMillis = pingIntervalMillis,            connectionRetryEnabled = connectionRetryEnabled        )        //检查该连接是否合格可用，合格则直接返回该连接        if (candidate.isHealthy(doExtensiveHealthChecks)) {            return candidate        }        //如果该连接不合格，标记为不可用，从连接池中移除        candidate.noNewExchanges()        ...省略代码...    }}

