所以核心方法就是findConnection
private fun findConnection(    connectTimeout: Int,    readTimeout: Int,    writeTimeout: Int,    pingIntervalMillis: Int,    connectionRetryEnabled: Boolean): RealConnection {    if (call.isCanceled()) throw IOException("Canceled")    //第一次，尝试重连 call 中的 connection，不需要去重新获取连接    val callConnection = call.connection // This may be mutated by releaseConnectionNoEvents()!    if (callConnection != null) {        var toClose: Socket? = null        synchronized(callConnection) {            if (callConnection.noNewExchanges || !sameHostAndPort(callConnection.route().address.url)) {                toClose = call.releaseConnectionNoEvents()            }        }        //如果 call 中的 connection 还没有释放，就重用它。        if (call.connection != null) {            check(toClose == null)            return callConnection        }        //如果 call 中的 connection 已经被释放，关闭Socket.        toClose?.closeQuietly()        eventListener.connectionReleased(call, callConnection)    }    //需要一个新的连接，所以重置一些状态    refusedStreamCount = 0    connectionShutdownCount = 0    otherFailureCount = 0    //第二次，尝试从连接池中获取一个连接，不带路由，不带多路复用    if (connectionPool.callAcquirePooledConnection(address, call, null, false)) {        val result = call.connection!!        eventListener.connectionAcquired(call, result)        return result    }    //连接池中是空的，准备下次尝试连接的路由    val routes: List&lt;Route&gt;?    val route: Route    ...省略代码...    //第三次，再次尝试从连接池中获取一个连接，带路由，不带多路复用    if (connectionPool.callAcquirePooledConnection(address, call, routes, false)) {        val result = call.connection!!        eventListener.connectionAcquired(call, result)        return result    }    route = localRouteSelection.next()}//第四次，手动创建一个新连接val newConnection = RealConnection(connectionPool, route)call.connectionToCancel = newConnectiontry {    newConnection.connect(        connectTimeout,        readTimeout,        writeTimeout,        pingIntervalMillis,        connectionRetryEnabled,        call,        eventListener    )} finally {    call.connectionToCancel = null}call.client.routeDatabase.connected(newConnection.route())//第五次，再次尝试从连接池中获取一个连接，带路由，带多路复用。//这一步主要是为了校验一下，比如已经有了一条连接了，就可以直接复用，而不用使用手动创建的新连接。if (connectionPool.callAcquirePooledConnection(address, call, routes, true)) {    val result = call.connection!!    nextRouteToTry = route    newConnection.socket().closeQuietly()    eventListener.connectionAcquired(call, result)    return result}synchronized(newConnection) {    //将手动创建的新连接放入连接池    connectionPool.put(newConnection)    call.acquireConnectionNoEvents(newConnection)}eventListener.connectionAcquired(call, newConnection)return newConnection}

一共做了5次尝试去得到连接：

第一次，尝试重连 call 中的 connection，不需要去重新获取连接。
第二次，尝试从连接池中获取一个连接，不带路由，不带多路复用。
第三次，再次尝试从连接池中获取一个连接，带路由，不带多路复用。
第四次，手动创建一个新连接。
第五次，再次尝试从连接池中获取一个连接，带路由，带多路复用。

client.networkInterceptors该拦截器称为网络拦截器，与client.interceptors一样也是由用户自己定义的，同样是以列表的形式存在OkHttpClient中。
他们的不同都是由于他们所处的位置不同所导致的，应用拦截器处于第一个位置，所以无论如何它都会被执行，而且只会执行一次。而网络拦截器处于倒数第二的位置，它不一定会被执行，而且可能会被执行多次，比如：在RetryAndFollowUpInterceptor失败或者CacheInterceptor直接返回缓存的情况下，网络拦截器是不会被执行的。
CallServerInterceptor到了这里，客户端与服务器已经建立好了连接，接着就是将请求头与请求体发送给服务器，以及解析服务器返回的response了。
class CallServerInterceptor(private val forWebSocket: Boolean) : Interceptor {    @Throws(IOException::class)    override fun intercept(chain: Interceptor.Chain): Response {        val realChain = chain as RealInterceptorChain        val exchange = realChain.exchange!!        val request = realChain.request        val requestBody = request.body        var invokeStartEvent = true        var responseBuilder: Response.Builder? = null        try {            //写入请求头            exchange.writeRequestHeaders(request)            //如果不是GET请求，并且请求体不为空            if (HttpMethod.permitsRequestBody(request.method) &amp;&amp; requestBody != null) {                //当请求头为"Expect: 100-continue"时，在发送请求体之前需要等待服务器返回"HTTP/1.1 100 Continue" 的response，如果没有等到该response，就不发送请求体。                //POST请求，先发送请求头，在获取到100继续状态后继续发送请求体                if ("100-continue".equals(request.header("Expect"), ignoreCase = true)) {                    //刷新请求，即发送请求头                    exchange.flushRequest()                    //解析响应头                    responseBuilder = exchange.readResponseHeaders(expectContinue = true)                    exchange.responseHeadersStart()                    invokeStartEvent = false                }                //写入请求体                if (responseBuilder == null) {                    if (requestBody.isDuplex()) {                        //如果请求体是双公体，就先发送请求头，稍后在发送请求体                        exchange.flushRequest()                        val bufferedRequestBody = exchange.createRequestBody(request, true).buffer()                        //写入请求体                        requestBody.writeTo(bufferedRequestBody)                    } else {                        //如果获取到了"Expect: 100-continue"响应，写入请求体                        val bufferedRequestBody = exchange.createRequestBody(request, false).buffer()                        requestBody.writeTo(bufferedRequestBody)                        bufferedRequestBody.close()                    }                    ···省略代码···                    //请求结束，发送请求体                    exchange.finishRequest()                    ···省略代码···                    try {                        if (responseBuilder == null) {                            //读取响应头                            responseBuilder = exchange.readResponseHeaders(expectContinue = false)!!                            ···省略代码···                            //构建一个response                            var response = responseBuilder                                .request(request)                                .handshake(exchange.connection.handshake())                                .sentRequestAtMillis(sentRequestMillis)                                .receivedResponseAtMillis(System.currentTimeMillis())                                .build()                            var code = response.code                            ···省略代码···                            return response                            ···省略代码···

写入发送请求头，然后根据条件是否写入发送请求体，请求结束。解析服务器返回的请求头，然后构建一个新的response，并返回。 这里CallServerInterceptor是拦截器责任链中最后一个拦截器了，所以他不会再调用chain.proceed()方法往下执行，而是将这个构建的response往上传递给责任链中的每个拦截器。
总结

**addInterceptor(Interceptor)**，处理原始请求和最终的响应：可以添加自定义header、通用参数、参数加密、网关接入。由开发者设置的，会按照开发者的要求，在所有的拦截器处理之前进行最早的拦截处理，比如一些公共参数，Header都可以在这里添加。
RetryAndFollowUpInterceptor，处理错误重试和重定向，这里会对连接做一些初始化工作，以及请求失败的充实工作，重定向的后续请求工作。跟他的名字一样，就是做重试工作还有一些连接跟踪工作。
BridgeInterceptor，应用层和网络层的桥接拦截器，主要工作是为请求添加cookie、添加固定的header，比如Host、Content-Length、Content-Type、User-Agent等等，然后保存响应结果的cookie，如果响应使用gzip压缩过，则还需要进行解压。为用户构建一个能够进行网络访问的请求，同时后续工作将网络请求回来的响应Response转化为用户可用的Response。
CacheInterceptor，这里主要是处理cache相关处理，会根据OkHttpClient对象的配置以及缓存策略对请求值进行缓存，而且如果本地有了可⽤的Cache，就可以在没有网络交互的情况下就返回缓存结果。如果命中缓存则不会发起网络请求
ConnectInterceptor，连接拦截器，内部会维护一个连接池，负责连接复用、创建连接（三次握手等等）、释放连接以及创建连接上的socket流。建立TCP连接或者TLS连接，以及负责编码解码的HttpCodec
networkInterceptors，开发者自己设置的，所以本质上和第一个拦截器差不多，但是由于位置不同，所以用处也不同。这个位置添加的拦截器可以看到请求和响应的数据了，所以可以做一些网络调试。
CallServerInterceptor，这里就是进行网络数据的请求和响应了，也就是实际的网络I/O操作，通过socket读写数据。

