//RxJava2CallAdapter.java@Override public Object adapt(Call&lt;R&gt; call) {  //1 把Call包装成一个Observable对象  Observable&lt;Response&lt;R&gt;&gt; responseObservable = isAsync      ? new CallEnqueueObservable&lt;&gt;(call)      : new CallExecuteObservable&lt;&gt;(call);  Observable&lt;?&gt; observable;  if (isResult) {    observable = new ResultObservable&lt;&gt;(responseObservable);  } else if (isBody) {    observable = new BodyObservable&lt;&gt;(responseObservable);  } else {    observable = responseObservable;  }  if (scheduler != null) {    observable = observable.subscribeOn(scheduler);  }  if (isFlowable) {    return observable.toFlowable(BackpressureStrategy.LATEST);  }  //2  if (isSingle) {    return observable.singleOrError();  }  if (isMaybe) {    return observable.singleElement();  }  if (isCompletable) {    return observable.ignoreElements();  }  return RxJavaPlugins.onAssembly(observable);}


